import json
from pathlib import Path
root=Path('code/V4/runs/R74_adaptive_incomplete_acquisition')
for name in ('current_status.json','pipeline_status.json','probe_initialization.json'):
    path=root/name
    if path.exists():
        value=json.loads(path.read_text())
        if name=='current_status.json':
            value={key:value.get(key) for key in ('stage','updated_utc','split','problem','successful_updates','last_batch','last_metrics')}
        print(json.dumps({'file':name,'value':value}))
print(json.dumps({'delivery_files_present':[str(path) for path in root.glob('*delivery*')]}))
PY"

