from pathlib import Path
root=Path('code/V4/runs/R74_adaptive_incomplete_acquisition')
for name in ('failures.jsonl','delivery_formal_failure_observation.json'):
    p=root/name
    if p.exists():
        if p.suffix=='.jsonl':
            value=[json.loads(line) for line in p.read_text().splitlines() if line.strip()]
        else:
            value=json.loads(p.read_text())
        print(json.dumps({'file':name,'value':value}))
